import { z } from 'zod';

/** Board columns. Ticket2PR owns the status, Trello owns the content (spec §6.3). */
export const CARD_STATUSES = ['NEW', 'IN_PROGRESS', 'REVIEW', 'DONE'] as const;
export const cardStatusSchema = z.enum(CARD_STATUSES);
export type CardStatus = z.infer<typeof cardStatusSchema>;

export const SYNC_TRIGGERS = ['AUTO', 'MANUAL'] as const;
export const syncTriggerSchema = z.enum(SYNC_TRIGGERS);
export type SyncTrigger = z.infer<typeof syncTriggerSchema>;

/** cuid ids generated by Prisma. */
export const idSchema = z.string().trim().min(1).max(64);

/** Trello object ids are 24-char hex strings. */
export const trelloIdSchema = z
  .string()
  .trim()
  .regex(/^[0-9a-f]{24}$/i, 'Invalid Trello id');
